/**
 * Jquery Number Formatting Mask
 * https://www.jqueryscript.net/demo/jQuery-Plugin-For-Number-Input-Formatting-Mask-Number/jquery.masknumber.js
 */
(function (factory) {

    if (typeof define === 'function' && define.amd) {
        define(['jquery'], factory);
    } else if (typeof exports === 'object') {
        module.exports = factory(require('jquery'));
    } else {
        factory(jQuery || Zepto);
    }

}(function($) {

    $.fn.maskNumber = function(options) {

        var settings = $.extend({}, $.fn.maskNumber.defaults, options);
        settings = $.extend(settings, options);
        settings = $.extend(settings, this.data());

        this.keyup(function() {
            format(this, settings);
        });

        return this;
    };

    $.fn.maskNumber.defaults = {
        thousands: ",",
        decimal: ".",
        integer: false,
    };

    function format(input, settings) {
        var inputValue = input.value;
        inputValue = removeNonDigits(inputValue);
        if (!settings.integer) {
            inputValue = addDecimalSeparator(inputValue, settings);
        }
        inputValue = addThousandSeparator(inputValue, settings);
        inputValue = removeLeftZeros(inputValue);
        applyNewValue(input, inputValue);
    }

    function removeNonDigits(value) {
        return value.replace(/\D/g, "");
    }

    function addDecimalSeparator(value, settings) {
        value = value.replace(/(\d{2})$/, settings.decimal.concat("$1"));
        value = value.replace(/(\d+)(\d{3}, \d{2})$/g, "$1".concat(settings.thousands).concat("$2"));
        return value;
    }

    function addThousandSeparator(value, settings) {
        var totalThousandsPoints = (value.length - 3) / 3;
        var thousandsPointsAdded = 0;
        while (totalThousandsPoints > thousandsPointsAdded) {
            thousandsPointsAdded++;
            value = value.replace(/(\d+)(\d{3}.*)/, "$1".concat(settings.thousands).concat("$2"));
        }

        return value;
    }

    function removeLeftZeros(value) {
        return value.replace(/^(0)(\d)/g,"$2");
    }

    function applyNewValue(input, newValue) {
        if (input.value != newValue) {
            input.value = newValue;
        }
        $(input).trigger('change', input.value);
    }

}));

var searchTable = null;
var totalNominations = 0;
var totalSold = 0;
var minForLitterDonation = 0;

jQuery(document).ready(function() {

    // Populate global values
    totalSold = jQuery('#total_jugs_sold').val();
    minForLitterDonation = jQuery('#minimum_amount_for_litter').val();

    jQuery.fn.dataTable.Api.register( 'processing()', function ( show ) {
        return this.iterator( 'table', function ( ctx ) {
            ctx.oApi._fnProcessingDisplay( ctx, show );
        } );
    } );

    var buttonExportOptions = {
        'exportOptions': {
            orthogonal: 'filter',
            columns: ':visible'
        }
    }

    searchTable = jQuery('table.shelters-search').DataTable({
        'scrollX': true,
        'processing': true,
        'dom': 'Bfrtip',
        'select': true,
        'buttons': [
            {
                extend: 'selectAll',
                className: 'button'
            },
            {
                extend: 'selectNone',
                className: 'button'
            },
            {
                extend: 'collection',
                autoClose: true,
                className: 'button',
                text: 'Export',
                buttons: [
                    $.extend( true, {}, buttonExportOptions, {
                        extend: 'excel',
                        className: 'button'
                    } ),
                    $.extend( true, {}, buttonExportOptions, {
                        extend: 'pdf',
                        className: 'button'
                    } ),
                    $.extend( true, {}, buttonExportOptions, {
                        extend: 'copy',
                        className: 'button'
                    } )
                ]
            },
            {
                extend: 'collection',
                text: 'Bulk Actions',
                className: 'disabled dt-button-bulk-actions button',
                autoClose: true,
                buttons: [
                    { text: 'Send Notifications', className: 'button', action: function () {
                        var data = searchTable.rows( { selected: true } ).data().pluck('shelter_post_id');
                        var shelters = new Array();
                        $.each( data, function(k, v) {
                            shelters.push( v );
                        });
                        show_status_message( 'Requesting notifications be sent to shelters...', 'pending' );
                        bulk_action( 'donation_send_notifications', { 'shelters': shelters} );
                    } },
                    { text: 'Include in Donation', className: 'button',   action: function () {
                        var data = searchTable.rows( { selected: true } ).data().pluck('shelter_post_id');
                        var shelters = new Array();
                        $.each( data, function(k, v) {
                            shelters.push( v );
                        });
                        show_status_message( 'Submitting shelters for inclusion in the donation...', 'pending' );
                        bulk_action( 'donation_include_in_donation', { 'shelters': shelters}  );

                    } },
                    { text: 'Exclude from Donation', className: 'button', action: function () {
                        var data = searchTable.rows( { selected: true } ).data().pluck('shelter_post_id');
                        var shelters = new Array();
                        $.each( data, function(k, v) {
                            shelters.push( v );
                        });
                        show_status_message( 'Submitting shelters for exclusion in the donation...', 'pending' );
                        bulk_action( 'donation_exclude_from_donation', { 'shelters': shelters }  );
                    } },
                    { text: 'Mark as Completed', className: 'button', action: function () {
                        var data = searchTable.rows( { selected: true } ).data().pluck('shelter_post_id');
                        var shelters = new Array();
                        $.each( data, function(k, v) {
                            shelters.push( v );
                        });
                        show_status_message( 'Submitting shelters to be marked as completed...', 'pending' );
                        bulk_action( 'donation_mark_as_completed', {shelters: shelters} );
                    } },
                ],
                fade: true
            },
            {
                extend: 'collection',
                autoClose: true,
                className: 'button',
                text: 'Columns',
                buttons: [
                    {
                        extend: 'colvis',
                        className: 'button'
                    },
                    {
                        extend: 'colvisGroup',
                        className: 'button',
                        text: 'Show All',
                        show: ':hidden'
                    },
                    {
                        extend: 'colvisGroup',
                        className: 'button',
                        text: 'Show None',
                        hide: ':visible'
                    },
                ]
            }
        ],
        'language': {
            buttons: {
                selectAll: "Select All",
                selectNone: "Select None",
                colvis: "Columns"
            }
        },
        'aLengthMenu': [[25, 50, 75, -1], [25, 50, 75, "All"]],
        'iDisplayLength': 25,
        'order': [[ 0, "desc"], [ 2, "desc" ]],
        'columns'    : [
            {'className': 'dt-center', 'width': '60px', 'render': function( data, type, full, meta) {

                switch (full.donation_status_id) {
                    case '1':
                        var status = 'Pending Notification';
                        break;
                    case '2':
                        var status = 'Pending Address Confirmation';
                        break;
                    case '3':
                        var status = 'Pending Delivery';
                        break;
                    case '4':
                        var status = 'Completed';
                        break;
                    default:
                        var status = 'Not Participating';
                }

                if ( type === 'display' ) {

                    switch (full.donation_status_id) {
                        case '1':
                            html = '<span class="cp-donation-status-icon dashicons dashicons-email-alt" title="' + status + '"></span>';
                            break;
                        case '2':
                            html = '<span class="cp-donation-status-icon dashicons dashicons-clock" title="' + status + '"></span>';
                            break;
                        case '3':
                            html = '<span class="cp-donation-status-icon dashicons dashicons-location-alt" title="' + status + '"></span>';
                            break;
                        case '4':
                            html = '<span class="cp-donation-status-icon dashicons dashicons-thumbs-up" title="' + status + '"></span>';
                            break;
                        default:
                            var html = '<span class="cp-donation-status-icon dashicons dashicons-no-alt" title="' + status + '"></span>';
                    }

                    return '<div class="donation-shelter-status-wrapper">' + html + '</div>';

                } else if ( type === 'filter' ) {

                    return status;

                } else if ( type === 'sort' ) {
                    return full.donation_status_id;
                }

                return '-';

            } },
            {'data': 'post_title', width: '250px'},
            {'data': 'nominations', width: '150px', 'className': 'dt-center', 'render': function( data, type, full, meta ) {
                if ( type === 'display' ) {
                    return numeral(data).format('0,0') + ' <span>(' + ( ( data > 0 ) ? Math.ceil( ( data / totalNominations ) * 100 ) : 0 ) + '%)</span>';
                }
                return data;
            }},
            {'className': 'dt-center', width: '150px', 'render': function( data, type, full, meta ) {
                if ( type === 'display' ) {

                    if ( full.donation_status_id > 0 && full.donation_status_id < 4) {

                        var donationAmount = Math.ceil(( full.nominations / totalNominations ) * totalSold);
                        var donationType   = (donationAmount > minForLitterDonation) ? 'litter' : 'coupon';

                        var selected = (full.donation_type !== '' && full.donation_type !== null )
                            ? full.donation_type : donationType;

                        return '<select class="cp-shelter-donation-input-donation-type" name="shelters[' + full.shelter_post_id + '][donation_type]">' +
                            '<option value="" ' + ( ( selected === '' ) ? 'selected="selected"' : '' ) + '>Choose ...</option>' +
                            '<option value="litter" ' + ( ( selected === 'litter' ) ? 'selected="selected"' : '' ) + '>Litter</option>' +
                            '<option value="coupon" ' + ( ( selected === 'coupon' ) ? 'selected="selected"' : '' ) + '>Coupon</option>' +
                            '</select>';

                    } else if ( full.donation_status_id == '4' ) {
                        return ucwords( donationType );
                    }

                } else if ( type === 'filter' || type === 'sort' ){
                    return (full.donation_type !== '' && full.donation_type !== null ) ? full.donation_type : '';
                }

                return '-';

            }},
            {'className': 'dt-center', width: '150px', 'render': function( data, type, full, meta) {

                var donationAmount = Math.ceil( ( full.nominations / totalNominations ) * totalSold );

                donationAmount = (full.donation_amount !== '' && full.donation_amount !== null )
                    ? full.donation_amount : donationAmount;

                if ( type === 'display' ) {
                    if ( full.donation_status_id !== '0' && full.donation_status_id !== null ) {
                        return '<input class="cp-shelter-donation-input-donation-amount" type="text" style="width:75px;" name="shelters[' + full.shelter_post_id + '][donation_amount]" value="' + numeral(donationAmount).format('0,0') + '" readonly="readonly" />';
                    } else {
                        return '-';
                    }
                }
                return (donationAmount) ? donationAmount : 0;

            } },
            {'className': 'dt-center', width: '150px', 'render': function( data, type, full, meta) {

                var adjustedDonationAmount = full.adjusted_donation_amount;

                if ( type === 'display' ) {
                    // The shelter donation status can't be 'Not Participating' or 'Delivered'
                    if ( full.donation_status_id > 0 && full.donation_status_id < 4 ) {
                        return '<input class="cp-shelter-donation-input-donation-adjusted-amount" type="text" style="width:75px;" name="shelters[' + full.shelter_post_id + '][adjusted_donation_amount]" value="' + ( ( adjustedDonationAmount !== null && adjustedDonationAmount > 0 ) ? adjustedDonationAmount : '' ) + '"/>';
                    } else if ( full.donation_status_id === 4 && adjustedDonationAmount !== null && adjustedDonationAmount > 0) {
                        return adjustedDonationAmount;
                    } else {
                        return '-';
                    }
                }
                return (adjustedDonationAmount) ? adjustedDonationAmount : '';

            } },
            {'data': 'shelter_manager_email', visible: false, width: '150px'},
            {'data': 'shelter_phone', visible: false, width: '150px'},
            {'data': 'donation_shipping_address_1', visible: false, width: '150px'},
            {'data': 'donation_shipping_address_2', visible: false, width: '150px'},
            {'data': 'donation_shipping_city', visible: false, width: '150px'},
            {'data': 'donation_shipping_state', visible: false, width: '150px'},
            {'data': 'donation_shipping_zip_code', visible: false, width: '150px'},
            {'data': 'donation_shipping_name', visible: false, width: '150px'},
            {'data': 'donation_shipping_phone', visible: false, width: '150px'},
            {'data': 'donation_shipping_email', visible: false, width: '150px'},
            {'data': 'donation_pickup_from_warehouse', visible: false, width: '150px'},
            {'data': 'donation_pickup_location', visible: false, width: '150px'},
            {'data': 'donation_provide_freight_quote', visible: false, width: '150px'},
            {'data': 'donation_has_loading_dock', visible: false, width: '150px'},
            {'data': 'donation_has_forklift', visible: false, width: '150px'},
            {'data': 'donation_delivery_time', visible: false, width: '150px'},
            {'data': 'donation_business_hours', visible: false, width: '150px'},
            {'data': 'donation_residential_delivery', visible: false, width: '150px'}
        ],
        'ajax': function( data, callback, settings ) {

            data.post_id               = cp_donations_params.post_id;
            data.nonce                 = cp_donations_params.search_donation_shelters_nonce;
            data.nomination_start_date = jQuery('.cp-meta-box-donation-search-form :input[name="nomination_start_date"]').val();
            data.nomination_end_date   = jQuery('.cp-meta-box-donation-search-form :input[name="nomination_end_date"]').val();
            data.total_jugs_sold       = jQuery('.cp-meta-box-donation-search-form :input[name="total_jugs_sold"]').val();
            data.minimum_amount_for_litter = jQuery('.cp-meta-box-donation-search-form :input[name="minimum_amount_for_litter"]').val();
            data.action = 'cp_get_donation_shelters';

            show_status_message( 'Retrieving shelters...', 'pending' );

            jQuery.ajax({
                'url' : cp_donations_params.ajax_url,
                'type' : 'post',
                'data' : data,
                'success' : function( response ) {

                    if ( response.data && response.data.shelters && response.data.shelters.length > 0 ) {
                        var shelters = response.data.shelters;
                    }  else {
                        var shelters = [];
                    }

                    if ( response.data && response.data.total_nominations ) {
                        totalNominations = response.data.total_nominations;
                    }

                    $('#cp-donation-stats-total-nominations .display-value span').html( numeral(totalNominations).format('0,0') );

                    $(response.data.donation_status_totals).each( function( key, value ) {
                        $('#cp-donation-status-' + key + ' td.display-value span').html( value );
                    });

                    callback( {
                        recordsTotal: shelters.length,
                        recordsFiltered:  shelters.length,
                        data: shelters
                    });

                },
                'error' : function( response ) {
                    console.log(response);
                },
                'complete': function( response ) {
                    remove_status_message();
                }
            });

        }
    });

    searchTable.on( 'select', function ( e, dt, type, indexes ) {
        if ( type === 'row' && searchTable.rows( { selected: true } ).count() > 0) {
            $('.dt-button-bulk-actions').removeClass('disabled');
        }
    } );

    searchTable.on( 'deselect', function ( e, dt, type, indexes ) {
        if ( type === 'row' && searchTable.rows( { selected: true } ).count() === 0) {
            $('.dt-button-bulk-actions').addClass('disabled');
        }
    } );

    searchTable.on( 'draw.dt', function() {
        enableTipTip();
        enableInputMask();
    } );

    $('#cp_donation_shelter_send_donation_litter').click(function() {
        bulk_action( 'donation_send_notifications', { 'donation_type': 'litter' } );
    });

    $('#cp_donation_shelter_send_donation_coupon').click(function() {
        bulk_action( 'donation_send_notifications', { 'donation_type': 'coupon' } );
    });

    $('button').click( function() {
        var data = searchTable.$('input, select').serialize();
        return false;
    } );

    $( "#nomination_start_date" ).datepicker({
        dateFormat: 'mm/dd/yy'
    });
    $( "#nomination_end_date" ).datepicker({
        dateFormat: 'mm/dd/yy'
    });
    $( "#donation_end_date" ).datepicker({
        dateFormat: 'mm/dd/yy'
    });

    function enableTipTip() {
        $('.dataTables_scrollBody .cp-donation-status-icon').tipTip({
            defaultPosition: 'top',
            delay: 0
        });
    }

    function enableInputMask() {
        $(':input.number-format').maskNumber({
            integer: true
        });
    }

    /**
     * Perform action on a group of selected shelters
     *
     * @param action
     * @param shelters
     */
    function bulk_action( action, data )
    {
        data = ( typeof data !== 'undefined' ) ? data : {};

        data.post_id  = cp_donations_params.post_id;
        data.nonce    = cp_donations_params.search_donation_shelters_nonce;
        data.action   = 'cp_bulk_action_' + action;

        // Since we manually selected shelters to send to, treat it as a force send
        if ( action === 'donation_send_notifications'
            && typeof data.shelters === 'object'
            && data.shelters.length > 0 ) {
            data.force_notification = 1;
        }

        searchTable.clear().draw().processing( true );

        jQuery.ajax( {
            'url' : cp_donations_params.ajax_url,
            'type' : 'post',
            'data' : data,
            'success' : function( response ) {
                searchTable.ajax.reload();
                show_status_message( response.data.message, 'success' );
            },
            'error' : function( response ) {
                searchTable.ajax.reload();
                var errorMessage = (response.data && response.data.message) ? response.data.message : 'There was a problem with your request.';
                show_status_message( errorMessage, 'error' );
            },
            'complete': function( response ) {
            }
        } );
    }

    /**
     * Display a message to the user
     *
     * @param message
     * @param type
     */
    function show_status_message( message, type, removeAfter )
    {
        remove_status_message();

        var html = '<div class=" status status_' + type + '">' + message + '</div>';

        $('.cp-meta-box-donation-potential-shelters-results').prepend( html );

        if ( typeof removeAfter !== 'undefined' ) {
            $('.cp-meta-box-donation-potential-shelters-results div.status').delay(removeAfter).fadeOut();
        }

    }

    /**
     * Remove the status message
     */
    function remove_status_message()
    {
        $('.cp-meta-box-donation-potential-shelters-results div.status').remove();
    }

    function ucwords (str) {
        return (str + '').replace(/^([a-z])|\s+([a-z])/g, function ($1) {
            return $1.toUpperCase();
        });
    }
    
});